async function rows(p){return p.evaluate(()=>new Promise((resolve,reject)=>{const q=indexedDB.open('fmonitor2-fast-pilot');q.onerror=()=>reject(q.error);q.onsuccess=()=>{const db=q.result;if(!db.objectStoreNames.contains('operations')){db.close();return resolve({operations:[],photos:[]});}const t=db.transaction(['operations','photoBlobs']),o=t.objectStore('operations').getAll(),b=t.objectStore('photoBlobs').getAll();t.oncomplete=()=>{resolve({operations:o.result,photos:b.result.map(x=>({id:x.id,size:x.blob?.size}))});db.close();};};}));}
async function until(p,predicate,label,ms=10000){const end=Date.now()+ms;let value;do{value=await rows(p);if(predicate(value))return value;await pause(50);}while(Date.now()<end);throw new Error(label+' '+JSON.stringify(value.operations.map(x=>({type:x.type,status:x.status,base:x.baseRevision}))));}
async function login(p,email=c.email){await p.goto(c.origin+'/pilot/login');await p.locator('[name=email]').fill(email);await p.locator('button[type=submit]').click();await p.locator('[name=password]').fill(c.password);await p.locator('button[type=submit]').click();await p.waitForURL(u=>!u.pathname.includes('/login'));}
