async function item(p,id){const target=p.locator(`[data-check-item="${id}"] .fm2-check-toggle`);const section=p.locator(`[data-check-section]:has([data-check-item="${id}"]) .fm2-section-toggle`);if(await section.getAttribute('aria-expanded')==='false')await section.click();await target.click();}
async function photo(p,seed=1,name='field.png') {const base64=await p.evaluate(seed=>{const cv=document.createElement('canvas');cv.width=8;cv.height=8;const x=cv.getContext('2d');x.fillStyle=`rgb(${seed},40,80)`;x.fillRect(0,0,8,8);return cv.toDataURL('image/png').split(',')[1];},seed);const toggle=p.locator('[data-check-section="1"] .fm2-section-toggle');if(await toggle.getAttribute('aria-expanded')==='false')await toggle.click();await p.locator('[data-check-section="1"] [data-photo-input]').last().setInputFiles({name,mimeType:'image/png',buffer:Buffer.from(base64,'base64')});return Buffer.from(base64,'base64');}
